source='''from collections import deque

def transform(grid):
    """Fill enclosed background components: odd area with 7, even area with 2."""
    g=[row[:] for row in grid]
    h=len(g); w=len(g[0]) if h else 0
    if not h or not w: return g
    bg=g[0][0]
    seen=set()
    # Mark background reachable from the outer edge. Any remaining background
    # component is enclosed by the drawn shapes.
    q=deque()
    for r in range(h):
        for c in (0,w-1):
            if g[r][c]==bg and (r,c) not in seen:
                seen.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if g[r][c]==bg and (r,c) not in seen:
                seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
            if 0<=nr<h and 0<=nc<w and (nr,nc) not in seen and g[nr][nc]==bg:
                seen.add((nr,nc)); q.append((nr,nc))
    for r in range(h):
        for c in range(w):
            if g[r][c]==bg and (r,c) not in seen:
                comp=[]; q=deque([(r,c)]); seen.add((r,c))
                while q:
                    cr,cc=q.popleft(); comp.append((cr,cc))
                    for nr,nc in ((cr-1,cc),(cr+1,cc),(cr,cc-1),(cr,cc+1)):
                        if 0<=nr<h and 0<=nc<w and (nr,nc) not in seen and g[nr][nc]==bg:
                            seen.add((nr,nc)); q.append((nr,nc))
                fill=7 if len(comp)%2 else 2
                for cr,cc in comp: g[cr][cc]=fill
    return g
'''
